package io.github.ningpp.compat;

/** Replacement for System.Management.Automation.RemoteException (generated by CSharpToJava converter). */
public class RemoteException extends RuntimeException {
    private int hresult;
    public RemoteException() { super(); }
    public RemoteException(String message) { super(message); }
    public RemoteException(String message, Throwable cause) { super(message, cause); }

    public int getHResult() { return hresult; }
    public void setHResult(int value) { this.hresult = value; }
}
